        strobe_reg_InvIn_PWM_L_safe <= '0';
      ELSIF enb = '1' THEN
        strobe_reg_InvIn_PWM_L_safe <= strobe_sw_InvIn_PWM_L_safe;
      END IF;
    END IF;
  END PROCESS reg_1_process;


  reg_InvIn_PWM_L_safe_3_1_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        data_reg_InvIn_PWM_L_safe_3_1 <= to_unsigned(0, 32);
      ELSIF enb = '1' AND reg_enb_InvIn_PWM_L_safe_3_1 = '1' THEN
        data_reg_InvIn_PWM_L_safe_3_1 <= data_write_unsigned;
      END IF;
    END IF;
  END PROCESS reg_InvIn_PWM_L_safe_3_1_process;


  write_reg_InvIn_PWM_L_safe(0) <= data_reg_InvIn_PWM_L_safe_1_1;
  write_reg_InvIn_PWM_L_safe(1) <= data_reg_InvIn_PWM_L_safe_2_1;
  write_reg_InvIn_PWM_L_safe(2) <= data_reg_InvIn_PWM_L_safe_3_1;

  sync_reg_InvIn_PWM_L_safe_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset_x = '1' THEN
        sync_reg_InvIn_PWM_L_safe_1 <= (OTHERS => to_unsigned(0, 32));
      ELSIF enb = '1' AND strobe_reg_InvIn_PWM_L_safe = '1' THEN
        sync_reg_InvIn_PWM_L_safe_1 <= write_reg_InvIn_PWM_L_safe;
      END IF;
    END IF;
  END PROCESS sync_reg_InvIn_PWM_L_safe_process;


  outputgen: FOR k IN 0 TO 2 GENERATE
    write_InvIn_PWM_L_safe(k) <= std_logic_vector(sync_reg_InvIn_PWM_L_safe_1(k));
  END GENERATE;

END rtl;

